create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null check(char_length(display_name) between 1 and 80), user_code text not null unique check(user_code ~ '^CNC-[A-Z0-9]{8}$'), created_at timestamptz not null default now());
create or replace function public.create_profile_for_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name,user_code) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),split_part(new.email,'@',1)),'CNC-'||upper(substr(md5(new.id::text||clock_timestamp()::text),1,8)));return new;end; $$;
drop trigger if exists conecta_profile_created on auth.users; create trigger conecta_profile_created after insert on auth.users for each row execute procedure public.create_profile_for_user();
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now());
create table if not exists public.conversation_members(conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(conversation_id,user_id));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,content text not null check(char_length(trim(content)) between 1 and 2000),created_at timestamptz not null default now());
create index if not exists messages_conversation_created_idx on public.messages(conversation_id,created_at); create index if not exists conversation_members_user_idx on public.conversation_members(user_id);
create or replace function public.is_conversation_member(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.conversation_members where conversation_id=cid and user_id=auth.uid()) $$;
create or replace function public.create_conversation_by_code(invite_code text) returns uuid language plpgsql security definer set search_path=public as $$ declare target uuid; existing uuid; created uuid; begin select id into target from public.profiles where user_code=upper(trim(invite_code));if target is null then raise exception 'Código de usuário não encontrado';end if;if target=auth.uid() then raise exception 'Você não pode conversar consigo mesmo';end if;select cm.conversation_id into existing from public.conversation_members cm where cm.user_id=auth.uid() and exists(select 1 from public.conversation_members x where x.conversation_id=cm.conversation_id and x.user_id=target) and 2=(select count(*) from public.conversation_members y where y.conversation_id=cm.conversation_id) limit 1;if existing is not null then return existing;end if;insert into public.conversations default values returning id into created;insert into public.conversation_members(conversation_id,user_id) values(created,auth.uid()),(created,target);return created;end; $$;
alter table public.profiles enable row level security;alter table public.conversations enable row level security;alter table public.conversation_members enable row level security;alter table public.messages enable row level security;
create policy "conecta profiles" on public.profiles for select to authenticated using(id=auth.uid() or exists(select 1 from public.conversation_members mine join public.conversation_members shared on shared.conversation_id=mine.conversation_id where mine.user_id=auth.uid() and shared.user_id=profiles.id));create policy "conecta member reads" on public.conversation_members for select to authenticated using(public.is_conversation_member(conversation_id));create policy "conecta conversation reads" on public.conversations for select to authenticated using(public.is_conversation_member(id));create policy "conecta message reads" on public.messages for select to authenticated using(public.is_conversation_member(conversation_id));create policy "conecta message sends" on public.messages for insert to authenticated with check(sender_id=auth.uid() and public.is_conversation_member(conversation_id));
grant usage on schema public to authenticated;grant select on public.profiles,public.conversations,public.conversation_members,public.messages to authenticated;grant insert on public.messages to authenticated;grant execute on function public.create_conversation_by_code(text) to authenticated;alter publication supabase_realtime add table public.messages;
